const t = await tools.browser.tabs.open({ url: "https://www.youtube.com/watch?v=hq3yfQnllfQ", focus: true });
await new Promise(r => setTimeout(r, 6000));
const res = await tools.browser.evaluate({
  tabID: t.id,
  script: `(() => {
    try {
      const pr = window.ytInitialPlayerResponse;
      if (!pr) return { err: 'no playerResponse' };
      const sb = pr.storyboards && pr.storyboards.playerStoryboardSpecRenderer;
      return {
        status: pr.playabilityStatus && pr.playabilityStatus.status,
        title: pr.videoDetails && pr.videoDetails.title,
        length: pr.videoDetails && pr.videoDetails.lengthSeconds,
        spec: sb && sb.spec ? sb.spec : null,
        thumb: pr.microformat && pr.microformat.playerMicroformatRenderer && pr.microformat.playerMicroformatRenderer.thumbnail && pr.microformat.playerMicroformatRenderer.thumbnail.thumbs
      };
    } catch (e) { return { err: String(e) }; }
  })()`
});
return res.value;

