            a = np.asarray(cell, dtype=float)
            frames.append(a.mean(axis=(0,1)))
    return frames

def frame_colors(name, cols, rows):
    files = sorted(glob.glob(f'sb/{name}_M*.jpg'), key=lambda p: int(p.rsplit('_M',1)[1].split('.')[0]))
    frames = []
    for f in files:
        frames += sheet_frames(f, cols, rows)
    # drop trailing near-black padding cells (storyboard padding), keep genuine dark scenes
    while frames and np.asarray(frames[-1]).mean() < 8:
        frames.pop()
    return np.array(frames)

