    im = Image.open('barcode.png').convert('RGB')
    a = np.asarray(im, dtype=float)
    sw = im.size[0]//100
    return np.array([a[:, k*sw:(k+1)*sw, :].mean(axis=(0,1)) for k in range(100)])

def resample(frames, n=100):
