real = real_barcode()
rows = []
mocks = {}
for k, name in names.items():
    fr = frame_colors(name, *grid[k])
    mock = resample(fr)
    mocks[k] = mock
    d = np.abs(mock-real).mean()
    rows.append((d, k, name, len(fr), durs[k]))
rows.sort()
print(f"{'rank':4} {'cand':4} {'name':10} {'frames':6} {'dur(s)':7} {'meanAbsDiff':12}")
for i,(d,k,name,nf,dur) in enumerate(rows,1):
    print(f"{i:<4} {k:4} {name:10} {nf:<6} {dur:<7} {d:.2f}")

# big comparison image: real on top, then each mock
def bar_img(colors):
    img = np.zeros((60, 1000, 3))
    for kk, c in enumerate(colors):
        img[:, kk*10:(kk+1)*10, :] = c
    return img.astype(np.uint8)
parts = [bar_img(real)]
for d,k,name,nf,dur in rows:
    label = np.full((30,1000,3),255,np.uint8)
    parts.append(np.vstack([label, bar_img(mocks[k])]))
Image.fromarray(np.vstack(parts)).save('compare_all.png')
print('saved compare_all.png')
